BEGIN;
DROP POLICY IF EXISTS tenant_access_insert ON public.fiscal_documents;
CREATE POLICY fiscal_documents_insert_draft ON public.fiscal_documents FOR INSERT TO authenticated WITH CHECK (private.is_tenant_member(tenant_id) AND status='draft' AND document_number IS NULL AND issue_date IS NULL);
DROP POLICY IF EXISTS tenant_access_update ON public.fiscal_documents;
CREATE POLICY fiscal_documents_update_draft ON public.fiscal_documents FOR UPDATE TO authenticated USING (private.is_tenant_member(tenant_id) AND status='draft') WITH CHECK (private.is_tenant_member(tenant_id) AND status='draft' AND document_number IS NULL AND issue_date IS NULL);
DROP POLICY IF EXISTS tenant_access_delete ON public.fiscal_documents;
CREATE POLICY fiscal_documents_delete_draft ON public.fiscal_documents FOR DELETE TO authenticated USING (private.is_tenant_member(tenant_id) AND status='draft' AND document_number IS NULL AND issue_date IS NULL);
DROP POLICY IF EXISTS fiscal_lines_insert ON public.fiscal_document_lines;
CREATE POLICY fiscal_lines_insert_draft ON public.fiscal_document_lines FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM public.fiscal_documents d WHERE d.id=document_id AND d.status='draft' AND d.document_number IS NULL AND d.issue_date IS NULL AND private.is_tenant_member(d.tenant_id)));
DROP POLICY IF EXISTS fiscal_lines_update ON public.fiscal_document_lines;
CREATE POLICY fiscal_lines_update_draft ON public.fiscal_document_lines FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.fiscal_documents d WHERE d.id=document_id AND d.status='draft' AND d.document_number IS NULL AND d.issue_date IS NULL AND private.is_tenant_member(d.tenant_id))) WITH CHECK (EXISTS (SELECT 1 FROM public.fiscal_documents d WHERE d.id=document_id AND d.status='draft' AND d.document_number IS NULL AND d.issue_date IS NULL AND private.is_tenant_member(d.tenant_id)));
DROP POLICY IF EXISTS fiscal_lines_delete ON public.fiscal_document_lines;
CREATE POLICY fiscal_lines_delete_draft ON public.fiscal_document_lines FOR DELETE TO authenticated USING (EXISTS (SELECT 1 FROM public.fiscal_documents d WHERE d.id=document_id AND d.status='draft' AND d.document_number IS NULL AND d.issue_date IS NULL AND private.is_tenant_member(d.tenant_id)));
DROP POLICY IF EXISTS tenant_access_update ON public.document_events;
DROP POLICY IF EXISTS tenant_access_delete ON public.document_events;
DROP POLICY IF EXISTS tenant_access_update ON public.audit_events;
DROP POLICY IF EXISTS tenant_access_delete ON public.audit_events;
DROP POLICY IF EXISTS tenant_access_insert ON public.tax_rules;
DROP POLICY IF EXISTS tenant_access_update ON public.tax_rules;
DROP POLICY IF EXISTS tenant_access_delete ON public.tax_rules;
CREATE POLICY tax_rules_admin_insert ON public.tax_rules FOR INSERT TO authenticated WITH CHECK (tenant_id IS NULL OR private.is_tenant_admin(tenant_id));
CREATE POLICY tax_rules_admin_update ON public.tax_rules FOR UPDATE TO authenticated USING (tenant_id IS NOT NULL AND private.is_tenant_admin(tenant_id)) WITH CHECK (tenant_id IS NOT NULL AND private.is_tenant_admin(tenant_id));
CREATE POLICY tax_rules_admin_delete ON public.tax_rules FOR DELETE TO authenticated USING (tenant_id IS NOT NULL AND private.is_tenant_admin(tenant_id));
DROP POLICY IF EXISTS tenant_access_insert ON public.document_series;
DROP POLICY IF EXISTS tenant_access_update ON public.document_series;
DROP POLICY IF EXISTS tenant_access_delete ON public.document_series;
CREATE POLICY series_admin_insert ON public.document_series FOR INSERT TO authenticated WITH CHECK (private.is_tenant_admin(tenant_id));
CREATE POLICY series_admin_update ON public.document_series FOR UPDATE TO authenticated USING (private.is_tenant_admin(tenant_id)) WITH CHECK (private.is_tenant_admin(tenant_id));
CREATE POLICY series_admin_delete ON public.document_series FOR DELETE TO authenticated USING (private.is_tenant_admin(tenant_id));
COMMIT;
